import React, { createContext, useContext } from "react";
import tlControle from "./generated/timeline.json";
import voControle from "./generated/voiceover.json";
import tlEconomie from "./generated/timeline-economie.json";
import voEconomie from "./generated/voiceover-economie.json";
import { FPS } from "./theme";

/**
 * Master timeline — generated by scripts/retime.py from the real voice-over durations
 * (lines chained back to back, no dead air). Animations and SFX are anchored to voice-over lines,
 * so they stay in sync whenever the voice changes.
 *
 * Two cuts share scenes 3–8:
 *  - "controle" : hook « Votre enfant utilise ChatGPT… mais apprend-il vraiment ? »
 *  - "economie" : hook « Un répétiteur, ça se paie chaque mois » (angle of the best-selling visual A)
 */
export type Variant = "controle" | "economie";
export type SceneId =
  | "S1-Accroche" | "S2-Probleme" | "S3-Tuteur" | "S4-Revelation"
  | "S5-Benefices" | "S6-Methode" | "S7-Offre" | "S8-Appel";
type Scene = { id: SceneId; from: number; to: number; lines: string[] };
export type Line = { id: string; start: number; duration: number; text: string };
type Raw = { tl: { total: number; scenes: unknown[] }; vo: { lines: Line[] } };

const RAW: Record<Variant, Raw> = {
  controle: { tl: tlControle, vo: voControle },
  economie: { tl: tlEconomie, vo: voEconomie },
};

export const OVERLAP = 8; // frames of cross-fade between scenes

export const makeTimeline = (variant: Variant) => {
  const { tl, vo } = RAW[variant];
  const SCENES = tl.scenes as Scene[];
  const LINES = vo.lines;
  const line = (id: string) => {
    const l = LINES.find((x) => x.id === id);
    if (!l) throw new Error(`Unknown voice-over line ${id} (${variant})`);
    return l;
  };
  const sceneOfLine = (id: string) => {
    const s = SCENES.find((x) => x.lines.includes(id));
    if (!s) throw new Error(`Line ${id} belongs to no scene`);
    return s;
  };
  const scene = (id: SceneId) => SCENES.find((s) => s.id === id)!;
  /** Absolute time (s) of a voice-over line start (+ offset). */
  const lineAbs = (id: string, offset = 0) => line(id).start + offset;
  /** Frame, relative to the start of the line's scene, of a voice-over line start (+ offset in seconds). */
  const at = (id: string, offset = 0) => Math.round((line(id).start - sceneOfLine(id).from + offset) * FPS);
  /** Duration of a line in frames */
  const lineFrames = (id: string) => Math.round(line(id).duration * FPS);
  const sceneAbs = (id: SceneId, offset = 0) => scene(id).from + offset;
  const linesOf = (id: SceneId) => scene(id).lines;

  const s1 = linesOf("S1-Accroche");
  const s2 = linesOf("S2-Probleme");
  type Sfx = [string, number, number];
  /** Sound effects on the master timeline: [file, absolute second, volume] */
  const SFX: Sfx[] = [
    ["pop", sceneAbs("S1-Accroche", 0.33), 0.35],
    ...(variant === "controle" ? ([["pop", sceneAbs("S1-Accroche", 1.4), 0.35]] as Sfx[]) : []),
    ["whoosh", lineAbs(s1[1], -0.7), 0.45],
    ...SCENES.slice(1).map((s): Sfx => ["whoosh", s.from - 0.25, 0.5]),
    ...s2.slice(0, 4).map((id): Sfx => ["pop", lineAbs(id), 0.45]),
    ["whoosh", lineAbs(s2[4], -0.5), 0.4],
    ["pop", lineAbs("l09"), 0.4],
    ["pop", lineAbs("l09", 0.73), 0.45],
    ["riser", sceneAbs("S4-Revelation", -1.8), 0.5],
    ["impact", sceneAbs("S4-Revelation", 0.3), 0.75],
    ...["l12", "l13", "l14", "l15"].map((id): Sfx => ["ding", lineAbs(id, 0.13), 0.28]),
    ...["l13", "l14", "l15"].map((id): Sfx => ["whoosh", lineAbs(id, -0.45), 0.3]),
    ["pop", sceneAbs("S6-Methode", 0.6), 0.3],
    ["pop", sceneAbs("S6-Methode", 2.67), 0.3],
    ["whoosh", lineAbs("l18", -0.45), 0.4],
    ...(variant === "economie" ? ([["pop", lineAbs("e19", 0.2), 0.4], ["pop", lineAbs("e19", 1.6), 0.4]] as Sfx[]) : []),
    ["success", lineAbs("l20"), 0.5],
    ["pop", lineAbs("l22", -1.2), 0.4],
    ["click", lineAbs("l22", 0.6), 0.8],
    ["success", lineAbs("l22", 0.65), 0.3],
  ];
  return {
    variant,
    SCENES,
    LINES,
    SFX,
    TOTAL_FRAMES: Math.round(tl.total * FPS),
    music: variant === "controle" ? "audio/music.mp3" : `audio/music-${variant}.mp3`,
    at,
    lineAbs,
    lineFrames,
    linesOf,
  };
};

export type Timeline = ReturnType<typeof makeTimeline>;
const Ctx = createContext<Timeline>(makeTimeline("controle"));
export const TimelineProvider: React.FC<{ variant: Variant; children: React.ReactNode }> = ({ variant, children }) =>
  React.createElement(Ctx.Provider, { value: makeTimeline(variant) }, children);
/** Timeline of the cut being rendered (scene timings, voice-over anchors). */
export const useTL = () => useContext(Ctx);

export const TOTAL_FRAMES_OF = (v: Variant) => makeTimeline(v).TOTAL_FRAMES;
export const SCENES_CONTROLE = makeTimeline("controle").SCENES;
